const text = $input.first().json.choices[0].message.content;
const withoutThoughts = text.replace(/<thought>[\s\S]*?<\/thought>/gi, '');
const cleaned = withoutThoughts.trim().replace(/^```(?:json)?\s*|\s*```$/g, '');
const parsed = JSON.parse(cleaned);
const bookingLink = $vars.CAL_COM_BOOKING_LINK || 'https://cal.com/your-team/intro';
parsed.body = parsed.body.replace('{{booking_link}}', bookingLink);
return [{ json: { leadId: $('Sign: Get Prompt').first().json.leadId, orgId: $('Sign: Get Prompt').first().json.orgId, agentId: $('GET Agent Prompt (scheduler)').first().json.agent.id, bookingLink, ...parsed } }];

const res = $input.first().json;
if (res.ErrorCode !== 0) {
  throw new Error(`Postmark error ${res.ErrorCode}: ${res.Message}`);
}
return [{ json: { messageId: res.MessageID } }];

const crypto = require('crypto');
const secret = $vars.N8N_WEBHOOK_SECRET;
const timestamp = Date.now();
const p = $('Parse Booking Message').first().json;
const messageId = $json.messageId;
const body = { event: 'meeting.booked', orgId: p.orgId, leadId: p.leadId, agentType: 'scheduler', input: {}, output: { bookingLink: p.bookingLink, subject: p.subject, messageId }, requiresHumanReview: false };
const rawBody = JSON.stringify(body);
const signature = crypto.createHmac('sha256', secret).update(`${timestamp}.${rawBody}`).digest('hex');
return [{ json: { rawBody, timestamp, signature } }];
